    {
      "card_ids": ["C15"],
      "claim": "Rolipram had 73% oral bioavailability in healthy volunteers and contains a lactam/aromatic ether framework; high transfer supports high F for the query's isoindolinone-glutarimide system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ondansetron had mean absolute bioavailability of 61% in healthy volunteers (range ~50-70%), showing that a moderately metabolized heterocyclic drug still exceeds the 20% threshold; supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Oxcarbazepine had almost complete oral bioavailability (95-99%) in humans, providing a strong example of a cyclic amide/imide-like drug with excellent absorption; supports high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
